<?php
namespace App\Filament\Resources\ProductAttributes;
use App\Filament\Resources\Concerns\AdminResource;use App\Filament\Resources\ProductAttributes\Pages\ManageProductAttributes;use App\Models\ProductAttribute;
use BackedEnum;use Filament\Actions\BulkActionGroup;use Filament\Actions\DeleteAction;use Filament\Actions\DeleteBulkAction;use Filament\Actions\EditAction;use Filament\Forms\Components\Select;use Filament\Forms\Components\TextInput;use Filament\Forms\Components\Toggle;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables\Columns\IconColumn;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;
class ProductAttributeResource extends AdminResource {protected static ?string $model=ProductAttribute::class;protected static string $viewPermission='catalog.view';protected static ?string $managePermission='catalog.update';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedAdjustmentsHorizontal;protected static ?string $navigationLabel='Thuộc tính';protected static string|\UnitEnum|null $navigationGroup='Sản phẩm';protected static ?int $navigationSort=70;public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->label('Tên')->required(),TextInput::make('code')->label('Mã')->required()->unique(ignoreRecord:true),Select::make('display_type')->label('Kiểu hiển thị')->options(['select'=>'Danh sách','color'=>'Màu','text'=>'Văn bản','number'=>'Số'])->default('select')->required(),Toggle::make('is_filterable')->label('Dùng để lọc')->default(true)] )->columns(2);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Tên')->searchable(),TextColumn::make('code')->label('Mã'),TextColumn::make('display_type')->label('Kiểu'),TextColumn::make('values_count')->counts('values')->label('Giá trị'),IconColumn::make('is_filterable')->label('Lọc')->boolean()])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);}public static function getPages():array{return ['index'=>ManageProductAttributes::route('/')];}}
